ref_dict.lem:harmonic-SS:
\begin{lem}\label{lem:harmonic-SS}
Let
\[
H_\ell(N) := \sum_{\substack{n\le N\\ \omega(n)=\Omega(n)=\ell}} \frac1n.
\]Then for every $0<\eta<1$ we have
\begin{equation}\label{eq:H-ell-lower}
  H_\ell(N) \gg_\eta \frac{(\log\log N)^\ell}{\ell!}
  \qquad (N\to\infty,\ 1\le \ell\le (1-\eta)\log\log N).
\end{equation}
\end{lem}

ref_dict.thm:B-implies-A:
\begin{thm}\label{thm:B-implies-A}
Fix $k\ge 3$. Then, as $N\to\infty$,
\[
f_k(N)\ll (\log N)^{\mu_k^{\mathrm S}-1+o(1)}.
\]
\end{thm}

ref_dict.thm:mu-lb-implies-f-lb:
\begin{thm}\label{thm:mu-lb-implies-f-lb}
Fix $k\ge 3$. Then, as $N\to\infty$,
\[f_k(N) \ge (\log N)^{\log\mu_k^{\mathrm S} - o(1)}.\]
\end{thm}

stem_triviality.reason:
The correct lower bound is of the form
f_k(N) \ge (\log N)^{c_k-o(1)}
as N\to\infty, with c_k = (k-2)/(e((k-2)!)^{1/(k-2)}). The predicted answer instead gives a much weaker lower bound of order (\log\log N)^{k-2}. Since (\log\log N)^{k-2} is asymptotically far smaller than any positive power of \log N, this is not an equivalent rephrasing or matching asymptotic bound.

theorem.content:
\label{thm:main}
Suppose that $X_1(M,MN)$ has genus zero, and suppose that $p$ is a prime divisor of $MN$. Then there exists an explicit constant $\theta$ (see Table \ref{tab:mean_variance_II}), depending only on $M$, $N$, $K$, and $p$, such that
\begin{equation}\label{eq:main}
	\limsup_{B\to\infty} \frac{1}{\# \cE_{(M,MN)}(B; K)} \sum_{E\in \cE_{(M,MN)}(B;K)} \# \Sel_p(E) \gg \log(B)^{\theta}.
\end{equation}
If additionally
\begin{equation}
(M,N, p, \sG_{MN}(K))\not\in 
\begin{Bmatrix}
(1,5, 5, ({\mathbb Z}/5{\mathbb Z})^\times), (1,7, 7, \{1,4,7\} \text{ or } ({\mathbb Z}/7{\mathbb Z})^\times), \\
 (1, 10, 5, ({\mathbb Z}/10{\mathbb Z})^\times), (2,2, 2, \ast), (2, 6, 3, ({\mathbb Z}/6{\mathbb Z})^\times), \\ (3,3, 3, \ast), (3,6, 3, \ast), (4,4,2,({\mathbb Z}/4{\mathbb Z})^\times), (5,5,5,\ast)
\end{Bmatrix},
\end{equation}
then $\theta$ is positive, implying that the average size of the $p$-Selmer group is unbounded.

ref_dict.prop:elliptic_count_general:
\begin{proposition}\label{prop:elliptic_count_general}
Let $G\leq \GL_2(\Z/N\Z)$, and suppose that the modular curve $\cX_G$ is isomorphic to the weighted projective stack $\cP(w_0,w_1)$ over the number field $K$. 
Let $\delta(G)$ denote the weighted degree of the morphism $\phi_{O}:\cX_G\to\cX(1)$ that forgets the level structure, and suppose that $\gcd(w_0w_1, \delta(G))=1$. Define
\begin{equation}
 \alpha(G)\defeq\frac{w_0+w_1}{12 \delta(G)}\qquad \text{ and }\qquad
 \beta(G)\defeq \frac{\deg_{\Q}(K)-\min\{w_0,w_1\}}{12\delta(G)\deg_{\Q}(K)}.
 \end{equation}
Let $v\in \Val_0(K)$ be a finite place not above $2$ or $3$, and let $\Omega_v\subseteq\cP(w_0,w_1)(K_v)$ be a subset for which $\Omega_v^{\aff}$ is measurable and whose boundary has measure $m_v(\partial \Omega_v^{\aff})=0$. 
Then there exists an explicit constant $\kappa_G$, depending only on $G$ and $K$, such that
\begin{equation}
\cN_G(K,\Omega_v; B) 
 = m_v\left(\Omega_v^{\aff}\cap \cO_{K,v}^{2}\right)\kappa_G B^{\alpha(G)}
  + O\left(B^{\beta(G)}\right).
\end{equation}
\end{proposition}

ref_dict.thm:selmer_erdos_kac_prime:
\begin{theorem}\label{thm:selmer_erdos_kac_prime}
	Consider the family of elliptic curves $E$ over a number field $K$ with level structure $G=G(M,MN)$. Let $\Phi$ be a subgroup of $\Z/M\Z$ of prime order, and let $m$ be as in Table \ref{tab:mean_variance_II}. Let $\sG = \sG_m(K)$ denote the subgroup 
\begin{equation}
	\{a\in (\Z/m\Z)^\times : \exists \text{ infinitely many degree one primes $\p$ with } N_{K/\Q}(\p)\equiv a \pmod{m}\}.
\end{equation}
	Let $c_{\E}(G,\Phi,\sG)$ and $\c_{\V}(G,\Phi,sG)$ be the constants in Table \ref{tab:mean_variance_II}. 
	Then the logarithmic Selmer ratios $s(E)$ are normally distributed with mean
	\begin{equation}
		c_{\E}(G,\Phi,\sG)\log\log(B)+O(1)
	\end{equation}
	and variance
	\begin{equation}
		c_{\V}(G,\Phi,\sG)\log\log(B)+O(1).
	\end{equation}
\end{theorem}

