ref_dict.corB:
\begin{headcor}[\autoref{thm_main_zeta}]
	\label{corB}
	Let $I \subseteq J \subset R$ be two homogeneous ideals in a polynomial ring $R = \kk[x_0, \ldots,x_n]$.
	Then the following two conditions are equivalent:
	\begin{enumerate}[\;\;\rm (a)]
		\item $J$ is integral over $I$.
		\item $\zeta_I(t) = \zeta_J(t)$.
	\end{enumerate} 
\end{headcor}

ref_dict.thm_main:
\begin{theorem}
	\label{thm_main}
	Assume \autoref{setup_segre_int_dep}.
	Then the following five conditions are equivalent:
	\begin{enumerate}[\;\;\rm (a)]
		\item $\II_W$ is integral over $\II_Z$. 
		\item ${j_Z}_*\left(s(Z, X)\right) = {j_W}_*\left(s(W, X)\right)$ in $A_*(X)$.
		\item $\deg_\LL\left(s^i(Z, X)\right) = \deg_\LL\left(s^i(W, X)\right)$ for all $i \ge 0$.
		\item $\deg_\LL\left(\nu^i(\underline{\sigma}, X)\right) = \deg_\LL\left(\nu^i(\underline{\eta}, X)\right)$ for all $i \ge 0$.
		\item $\deg_\LL\left(\beta^i(\underline{\sigma}, X)\right) = \deg_\LL\left(\beta^i(\underline{\eta}, X)\right)$ for all $i \ge 0$.
	\end{enumerate} 
\end{theorem}

ref_dict.thm_main_zeta:
\begin{corollary}
	\label{thm_main_zeta}
	Let $J \subset R = \kk[x_0,\ldots,x_n]$ be a homogeneous ideal such that $J \supseteq I$.
	Then the following two conditions are equivalent:
	\begin{enumerate}[\;\;\rm (a)]
		\item $J$ is integral over $I$.
		\item $\zeta_I(t) = \zeta_J(t)$.
	\end{enumerate} 
\end{corollary}

