\begin{example}[Schur bundles of size $3$]\label{example:3}
		In this case we have three cases, namely $\alpha=(3),(2,1)$ and $(1,1,1)$. 
		\begin{description}
			\item[$\bullet\;\alpha=(3)$] It is easy to compute
			\[ \D_a(\schur_3)=\schur_2+\schur_1 2^{a-1}+3^{a-1},\quad \D_a\D_b(\schur_3)=\schur_1+2^{a-1}+2^{b-1}\quad\mbox{and}\quad \D_a\D_b\D_c(\schur_3)=1, \]
			from which we deduce the first values of $\ch_n(\Schur^3E)$:
			\begin{align*}
				\ch_1(\Schur^{3}E) = & \, \binom{r+2}{2}\ch_1(E), \\
				\ch_2(\Schur^{3}E) = & \, \binom{r+3}{2}\ch_2(E)+(r+2)\frac{\ch_1(E)^2}{2}, \\
				\ch_3(\Schur^{3}E) = & \, \frac{(r+3)(r+6)}{2}\ch_3(E)+(r+3)\ch_2(E)\ch_1(E) + \frac{\ch_1(E)^3}{6}, \\
				\ch_4(\Schur^{3}E) = & \, \frac{r^2+17r+54}{2}\ch_4(E)+(r+5)\ch_3(E)\ch_1(E)+(r+4)\frac{\ch_2(E)^2}{2}+\frac{\ch_2(E)\ch_1(E)^2}{2}.
			\end{align*}

			\item[$\bullet\;\alpha=(2,1)$] It is easy to see that
			\[ \D_{a}(\schur_{(2,1)})=\schur_{2}+\schur_{(1,1)}-3^{a-1},\quad \D_a\D_b(\schur_{(2,1)})=2\schur_1\qquad \mbox{and}\qquad \D_a\D_b\D_c(\schur_{(2,1)})=2, \]
			from which we deduce the first values of $\ch_n(\Schur^{(2,1)}E)$:
			\begin{align*}
				\ch_1(\Schur^{(2,1)}E) = & \, (r^2-1)\ch_1(E), \\
				\ch_2(\Schur^{(2,1)}E) = & \, (r^2-3)\ch_2(E)+2r\frac{\ch_1(E)^2}{2}, \\
				\ch_3(\Schur^{(2,1)}E) = & \, (r^2-9)\ch_3(E)+2r\ch_2(E)\ch_1(E) + 2 \frac{\ch_1(E)^3}{6}, \\
				\ch_4(\Schur^{(2,1)}E) = & \, (r^2-27)\ch_4(E)+2r\ch_3(E)\ch_1(E)+2r\frac{\ch_2(E)^2}{2}+2\frac{\ch_2(E)\ch_1(E)^2}{2}, \dots
			\end{align*}

			\item[$\bullet\;\alpha=(1,1,1)$] It is easy to compute
