An important problem in computational algebraic geometry is to compute Chern classes of $\Schur^\alpha E$ in terms of those of $E$. It is in principle possible to perform such computations using the splitting principle, but the combinatorics behind this approach is very cumbersome, see for example \cite{Dragutin, Manivel}, where the cases of symmetric and alternating powers were treated.
 In this short paper we provide a compact and effective solution to this problem.

The quantity $\D^{\nu}(\schur_\alpha)$, which is the new ingredient in the formula, is a purely combinatorial object which is easily computed in explicit examples, see Examples~\ref{example:2} and \ref{example:3} and Proposition~\ref{prop:ch of sym}.
 \medskip

\begin{thmB}[Theorem~\ref{thm:k}]
 For any $n\geq0$, the $n^{\operatorname{th}}$ twisted Chern character coefficient of $\Schur^\alpha E$ is
 \[ k_n(\Schur^\alpha E)=\sum_{\nu\vdash n}\rk(\D^\nu(\schur_\alpha))\,k^{(\nu)}(E), \]
 where the sum may be taken over the partitions of $n$ into parts that are all strictly larger than $1$.
 \end{thmB}

In our previous work \cite{DAFOa} we proved formulas expressing $k_2(\Schur^\alpha E)$ and $k_3(\Schur^\alpha E)$ as certain multiples of $k_2(E), k_3(E)$. Theorem B reinterprets those results as 
 \begin{align*}
 k_2(\Schur^\alpha E) = & \, \rk(\D_2(\schur_\alpha)) \, k_2(E)\, , \\
 k_3(\Schur^\alpha E) = & \, \rk(\D_3(\schur_\alpha)) \, k_3(E)\, ,
 \end{align*}
 and provides generalizations to all twisted Chern character coefficients $k_n$, see \S~\ref{section:k}.

\begin{thm}\label{thm:Chern}
 With notations as above, we have
 \[ \ch_n(\Schur^\alpha E)=\sum_{\nu\vdash n}\rk(\D^\nu(\schur_\alpha))\,\ch^{(\nu)}(E). \]
 \end{thm}

\begin{corollary}[\cite{Rubei}]\label{corollary:Rubei}
 With notations as above,
 \[ \ch_1(\Schur^\alpha E)=|\alpha|\frac{r_\alpha}{r}\ch_1(E), \]
 where $r_\alpha=\rk(\Schur^\alpha E)$.
 \begin{proof}
 From Theorem~\ref{thm:Chern} we obtain that
 $$\ch_1(\Schur^\alpha E) = \rk(\D_1(\schur_\alpha)) \ch_1(E).$$
 As $$\D_1 = \sum_{k \geq 0} \frac{\partial}{\partial \power_k}$$ and $\rk(\power_k) = r$ for every $k$, then
 $$\rk(\D_1(\schur_\alpha)) = \frac{1}{r} \rk\left(\sum_k \power_k \frac{\partial}{\partial \power_k} (\schur_\alpha)\right).$$ 
 The claim follows now by noticing that $\sum_k \power_k {\partial}/{\partial \power_k}$ acts on homogeneous elements via multiplication by their degree.
 \end{proof}
 \end{corollary}

\begin{thm}\label{thm:k}
 With notations as above,
 \[ k_n(\Schur^\alpha E)=\sum_{\nu\vdash n}\rk(\D^\nu(\schur_\alpha))\,k^{(\nu)}(E). \]
 \end{thm}

First of all, it is enough to prove that 
 \begin{equation}\label{eqn:in the proof of ch of sym} 
 \rk(\D_{\aaa_\nu}(\schur_m))=\sum_{1\leq\bbb\leq\aaa_\nu}\E(\overleftarrow{\aaa_\nu},\overleftarrow{\bbb})\binom{r+m+|\bbb|-\nu_1-1}{r+|\aaa_\nu|-1}. 
 \end{equation}
 In fact, this is exactly the coefficient in front of $\ch^{(\nu)}(E)$ in the formula for the Chern character, while for the twisted Chern character it is enough to notice that $k_1(E)=0$, so that every partition $\nu$ such that $\nu_1\geq1$ does not contribute to the formula. (The shift $\overleftarrow{\aaa_\nu}$ in the formula for the twisted Chern character is explained in Remark~\ref{rmk:bound}.)

\begin{example}[Schur bundles of size $2$]\label{example:2}
		Let us compute $\ch(\Schur^{\alpha}E)$ when $|\alpha|=2$. We have only two cases, namely the symmetric power $\Schur^2E$ and the exterior power $\extp^2 E$, corresponding to $\alpha=(1,1)$. 
		\begin{description}
			\item[$\alpha=(2)$] it is easy to see that the only non-zero derivatives of $\schur_2$ are
			\[ \D_a(\schur_2)=\schur_1+2^{a-1}\implies \rk(\D_a(\schur_2))=r+2^{a-1} \qquad\mbox{ and }\qquad\D_a\D_b(\schur_2)=1. \]
			Then the first values of $\ch_n(\Schur^2 E)$ are:
			\begin{align*}
				\ch_1(\Schur^{2}E) = & \, (r+1)\ch_1(E), \\
				\ch_2(\Schur^{2}E) = & \, (r+2)\ch_2(E)+\frac{\ch_1(E)^2}{2}, \\
				\ch_3(\Schur^{2}E) = & \, (r+4)\ch_3(E)+\ch_2(E)\ch_1(E), \\
				\ch_4(\Schur^{2}E) = & \, (r+8)\ch_4(E)+\ch_3(E)\ch_1(E)+\frac{\ch_2(E)^2}{2}, \dots
			\end{align*}

			\item[$\alpha=(1,1)$] it is easy to see that the only non-zero derivatives of $\schur_{(1,1)}$ are
			\[ \D_a(\schur_{(1,1)})=\schur_1-2^{a-1}\implies \rk(\D_a(\schur_2))=r-2^{a-1}\qquad\mbox{ and }\qquad\D_a\D_b(\schur_{(1,1)})=1. \]
			Then the first values of $\ch_n(\extp^2 E)$ are:
			\begin{align*}
				\ch_1(\extp^2E) = & \, (r-1)\ch_1(E), \\
				\ch_2(\extp^2E) = & \, (r-2)\ch_2(E)+\frac{\ch_1(E)^2}{2}, \\
				\ch_3(\extp^2E) = & \, (r-4)\ch_3(E)+\ch_2(E)\ch_1(E), \\
				\ch_4(\extp^2E) = & \, (r-8)\ch_4(E)+\ch_3(E)\ch_1(E)+\frac{\ch_2(E)^2}{2}, \dots
			\end{align*}
		\end{description}
	\end{example}

\begin{example}[Schur bundles of size $3$]\label{example:3}
		In this case we have three cases, namely $\alpha=(3),(2,1)$ and $(1,1,1)$. 
		\begin{description}
			\item[$\bullet\;\alpha=(3)$] It is easy to compute
			\[ \D_a(\schur_3)=\schur_2+\schur_1 2^{a-1}+3^{a-1},\quad \D_a\D_b(\schur_3)=\schur_1+2^{a-1}+2^{b-1}\quad\mbox{and}\quad \D_a\D_b\D_c(\schur_3)=1, \]
