We first note that hypothesis \eqref{(4)} already ensures that 
\[
1 < r_{j} \le p_{j} \qquad \text{for every } j \in J.
\] 
Moreover, by combining assumptions \eqref{(2)} and \eqref{(4)}, we obtain the stronger condition 
\[
r_{j} > p_{j} - 1, \qquad \forall\, j \in J.
\]

The following lemma will be of central importance in the remainder of the proof, and it will be especially needed in the passage to the limit.
\begin{lem}\label{lmq}
Assume that the assumptions \eqref{(2)}-\eqref{(6)} hold true.
Then, we have
\begin{equation}\label{ugest}
\int_{\Omega} u_{n}^{q\sigma_j}\left\vert D_{j} u_{n}\right\vert^{\sigma_j(p_{j}-1)}\;dx \leq C\quad\quad \forall \sigma_j<p_j^\prime.
\end{equation}
\end{lem}
\begin{proof}
 Taking $ \varphi(u_n)=1-\frac{1}{(1-u_n)^\lambda},$ with $\lambda>1,$ as test function in the weak formulation \eqref{(21)}, we get
\begin{equation*}
(\lambda-1)\sum_{j\in J}\int_{\Omega} \frac{[a(x)+u_n^q]\vert D_j u_n\vert^{p_{j}}}{(1+u_n)^\lambda}+\sum_{j\in J}\int_{\Omega}b(x)\frac{u_{n}\vert D_{j}u_{n}\vert^{p_{j}}}{\left( u_{n}+\frac{1}{n}\right)^{\theta+1}}\varphi =\int_\Omega f_n \varphi(u_n).
\end{equation*}
We recall that there exists a positive constant $\mathcal{C}$ such that
$$(a(x)+u_n^q) \geq \mathcal{C}(1+u_n)^q,\quad \quad \forall q>1.$$ 
Dropping the positive term and using the fact that $\vert \varphi(u_n)\vert\leq 1,$ we obtain
\begin{equation}\label{est1}
\sum_{j\in J}\int_{\Omega} \frac{\vert D_j u_n\vert^{p_j}}{(1+u_n)^{\lambda-q}}\leq\frac{1}{\mathcal{C}(\lambda-1)}\int_\Omega \vert f_n\vert .
\end{equation}
For $1 < \sigma_{j} < p'_{j} = \frac{p_{j}}{p_{j} - 1}$, an application of H\"older's inequality together with estimate \eqref{est1} yields, for every $j \in J$,
\begin{align*}
\int_{\Omega} u_{n}^{q \sigma_{j}(p_{j}-1)}\left\vert D_{j} u_{n}\right\vert^{\sigma_{j}(p_{j}-1)} \leq C\left( \int_{\Omega} (1+u_{n})^{\frac{\sigma_{j}(p_{j}-1)(\lambda-q+p_{j} q)}{p_{j}-\sigma_{j}(p_{j}-1)}}\right)^{\frac{p_{j}-\sigma_{j}(p_{j}-1)}{p_{j}}}.
\end{align*}
We now introduce the parameter $\sigma_{j} = \theta\frac{p_{j}}{p_{j}-1}$, with $\theta \in (0,1)$. Under this choice, one readily verifies that
$$
\frac{p_{j}-\sigma_{j}(p_{j}-1)}{p_{j}} = 1 - \theta,\quad \forall\; j\in J,$$
and
$$ \frac{\sigma_{j}(p_{j}-1)(\lambda-q+p_{j} q)}{p_{j}-\sigma_{j}(p_{j}-1)} = \frac{\theta}{1-\theta}[\lambda+q(p_{j}-1)],\quad \forall\; j\in J.
$$
Substituting into the previous estimate leads to
\begin{equation}
\label{E11}
\int_{\Omega} u_{n}^{q \sigma_{j}(p_{j}-1)}\left\vert D_{j} u_{n}\right\vert^{\sigma_{j}(p_{j}-1)} \leq C\left( \int_{\Omega}(1+ u_{n})^{\frac{\theta}{1-\theta}[\lambda+q(p_{j}-1)]}\right)^{1-\theta}, 
\end{equation}
for every $j\in J$. Hence, we deduce the following inequality:
\begin{align*}
&\prod_{i\in J}\left(\int_{\Omega} u_{n}^{q \sigma_{j}(p_{j}-1)}\left\vert D_{j} u_{n}\right\vert^{\sigma_{j}(p_{j}-1)}\;dx\right)^{\frac{1}{\theta p_{j}}}\\
&\quad \leq C\prod_{i\in J}\left( \int_{\Omega} (1+u_{n})^{\frac{\theta}{1-\theta}[\lambda+q(p_{j}-1)]}\;dx\right)^{\frac{1-\theta}{\theta p_{j}}}.
\end{align*}
By invoking the anisotropic inequality \eqref{(9)} with $\delta_{j} = \sigma_{j}(p_{j}-1) \leq p_{j}$ (due to $\theta < 1$), $t_{j} = q \geq 0$, and $\overline{\delta} = \theta \overline{p}$, we obtain
\begin{equation}\label{E12}
\left(\int_{\Omega}u_{n}^{r}\right)^{\frac{N}{\theta\overline{p}}-1} \leq C\prod_{i\in J}\left( \int_{\Omega} (1+u_{n})^{\frac{\theta}{1-\theta}[\lambda+q(p_{j}-1)]}\right)^{\frac{1-\theta}{\theta p_{j}}}.
\end{equation}
In order for the preceding inequality to hold uniformly for all $j \in J$, we must enforce that
$$
r = \frac{\theta}{1-\theta}[\lambda+q(p_{j}-1)], \quad \forall\, j\in J.
$$
This leads to the following system of equations:
\begin{align}
& r=\frac{1+q}{b_{j}(N-1)-1+\frac{1}{\theta p_{j}}}, \quad \forall j\in J, \label{S1} \\
& r=\frac{\theta}{1-\theta}[\lambda+q(p_{j}-1)], \quad \forall j\in J, \label{S2} \\
&\sum_{i\in J}b_{j}=1, \quad b_{j} \geq 0, \quad \forall j\in J. \label{S3}
\end{align}
By combining equations \eqref{S1} and \eqref{S3}, one deduces
$$
r = \frac{N(1+q)\theta \overline{p}}{N-\theta\overline{p}}.
$$
In parallel, equation \eqref{S2} yields
$$
\theta = \frac{N(\overline{p}-\lambda+q)}{\overline{p}[N(1+q)-q\overline{p}-\lambda+q]}.
$$
Since $q \geq 0$ and $\lambda > 1$, it follows that $0 < \theta < 1$. Consequently, by combining these expressions, we arrive at
$$
r = \frac{N(\overline{p}-\lambda+q)}{N-\overline{p}}.
$$
Using this value of $r$ in inequality \eqref{E12}, we find
$$
\left(\int_{\Omega}u_{n}^{r}\right)^{\frac{N}{\theta\overline{p}}-1} \leq C\left(\int_{\Omega}u_{n}^{r}\right)^{\frac{(1-\theta)N}{\theta \overline{p}}}.
$$
Since the assumption $\overline{p} < N$ ensures that the left-hand exponent exceeds the right-hand one, we conclude that $\{u_{n}\}$ is bounded in $L^{r}(\Omega)$. This bound, together with estimate \eqref{E11}, implies that
$$
\int_{\Omega} u_{n}^{q \sigma_{j}(p_{j}-1)}\left\vert D_{j} u_{n}\right\vert^{\sigma_{j}(p_{j}-1)} \leq C, \quad \forall\, j\in J.
$$
Given that $p_{j} > 2$ and $\sigma_{j} > 1$ for all $j\in\mathcal{E}$, we apply Hölder’s inequality to obtain
\begin{align*}
\int_{\Omega} u_{n}^{q \sigma_{j}} \left\vert D_{j} u_{n}\right\vert^{\sigma_{j}(p_{j}-1)} 
&= \int_{\left\{u_{n}<1\right\}} u_{n}^{q \sigma_{j}} \left\vert D_{j} u_{n}\right\vert^{\sigma_{j}(p_{j}-1)} \\
&\qquad+ \int_{\left\{u_{n} \geq 1\right\}} u_{n}^{q \sigma_{j}} \left\vert D_{j} u_{n}\right\vert^{\sigma_{j}(p_{j}-1)}\\
&\leq \int_{\Omega} \left\vert D_{j} \mathcal{T}_{1}(u_{n})\right\vert^{\sigma_{j}(p_{j}-1)}
+ \int_{\Omega} u_{n}^{q \sigma_{j}(p_{j}-1)} \left\vert D_{j} u_{n}\right\vert^{\sigma_{j}(p_{j}-1)} \\
&\leq C \left(\int_{\Omega} \left\vert D_{j} \mathcal{T}_{1}(u_{n})\right\vert^{p_{j}} \right)^{\frac{\sigma_{j}(p_{j}-1)}{p_{j}}} + C \\
&\leq C.
\end{align*}
Thus, it follows that the sequence $\left\lbrace u_{n}^{q}\left\vert D_{j} u_{n}\right\vert^{p_{j}-1}\right\rbrace$ is uniformly bounded in $L^{\sigma_{j}}(\Omega)$ for all $1 < \sigma_{j} < p'_{j}$ and for each $j \in J$.
\end{proof}
Let us specify some useful notation we will use from now on. For any \(n\in \mathbb{N}^{*}\) we define the following auxiliary functions:
\begin{equation*}
\mathcal{H}_{n}(l)=\int_{0}^{l}\frac{dt}{\left(t+\frac{1}{n}\right)^{\theta}},
\qquad
\mathcal{H}_{\infty}(l)=\int_{0}^{l}\frac{dt}{t^{\theta}},
\end{equation*}
and, let $\gamma=\frac{\nu}{\alpha}>0,$ we denote
\begin{equation*}
\Psi_{n}(l)=e^{-\gamma \mathcal{H}_{n}(l)},\qquad \Psi_{\infty}(l)=e^{-\gamma \mathcal{H}_{\infty}(l)}.
\end{equation*}
Note that, the function \(\mathcal{H}_{\infty}\) is well defined because \(\theta<1\). Moreover, it's clear that
$$\lim_{n\rightarrow \infty}\mathcal{H}_{n}(l)=\mathcal{H}_{\infty}(l)\text{ and }\lim_{n\rightarrow \infty}\Psi_{n}(l)=\Psi_{\infty}(l).$$
Observe that, for any \(\phi, u_{n}\in W_{0}^{1,(p_{j})}(\Omega)\cap L^{\infty}(\Omega)\) with \(\phi\ge0\) , we have \(\Psi_{n}(u_{n})\phi\in W_{0}^{1,(p_{j})}(\Omega)\cap L^{\infty}(\Omega)\).

