\begin{theorem}\label{thm:MSinfiniteICCsum}
Suppose $G _i$, $i\in I$, and $H _j$, $j\in J$, are ICC groups in the class $\mathcal{C}$, where $I,J$ are countable. If $G \coloneqq \bigoplus _{i\in I}G _i$ and $H \coloneqq \bigoplus _{j\in J} H _j$ are measure equivalent then $|I|=|J|$ and there exists a bijection $t:I\rightarrow J$ such that $G _i$ is measure equivalent with $H_{t(i)}$ for all $i\in I$.
\end{theorem}

ref_dict.torsion-free-family:
\begin{proposition}\label{torsion-free-family}
There exists a countably infinite family $\{B_d\}_{d\geq 1}$  of torsion-free, $4$-generated ICC groups in the class $\mathcal{C}$ which are pairwise not measure equivalent. 
\end{proposition}

ref_dict.prop:direct_sum_family:
\begin{proposition}\label{prop:direct_sum_family}
There exists a continuum sized family $\{A_c\}_{c\in I}$  of finitely generated ICC groups in the class $\mathcal{C}$ which are pairwise not measure equivalent. 
\end{proposition}

ref_dict.WR:
\begin{proposition}\label{WR}
For every $n\in\mathbb N$,  there exists a property (T) group $V\in\mathcal W\mathcal R(\mathbb F_n^{(\mathbb N)},B)$, where $B$ is a torsion-free (hence, ICC) hyperbolic group.

Moreover, if $\{A_k\}_{k=1}^\infty$ is a sequence of $n$-generated groups, then there exists a property (T) group belonging to $\mathcal W\mathcal R(\bigoplus_{k=1}^\infty A_k,B)$.
\end{proposition}

ref_dict.descend:
\begin{theorem}\label{descend}
Let $A$ and $C$ be any countable groups,  and $B$ and $D$ be ICC hyperbolic groups. Assume that $G\in\mathcal W\mathcal R(A,B)$ and $H\in \mathcal{W}\mathcal{R}(C,D)$ are measure equivalent groups. Then the groups $A^{(B)}$ and $C^{(D)}$ are measure equivalent.
\end{theorem}

selected.expanded_sketch:
In the remaining of the introduction, we outline the proof of the main theorem. The groups $\{G_x\}_{x\in\{0,1\}^{\mathbb N}}$ are constructed as wreath-like products (in the sense of \cite{CIOS23a,CIOS23b}) and the construction relies on four ingredients:
\begin{enumerate}
\item \begin{proposition}\label{torsion-free-family}
There exists a countably infinite family $\{B_d\}_{d\geq 1}$  of torsion-free, $4$-generated ICC groups in the class $\mathcal{C}$ which are pairwise not measure equivalent. 
\end{proposition}

\item \begin{proposition}\label{WR}
For every $n\in\mathbb N$,  there exists a property (T) group $V\in\mathcal W\mathcal R(\mathbb F_n^{(\mathbb N)},B)$, where $B$ is a torsion-free (hence, ICC) hyperbolic group.

Moreover, if $\{A_k\}_{k=1}^\infty$ is a sequence of $n$-generated groups, then there exists a property (T) group belonging to $\mathcal W\mathcal R(\bigoplus_{k=1}^\infty A_k,B)$.
\end{proposition}

\item We first use the following theorem.

\begin{theorem}\label{descend}
Let $A$ and $C$ be any countable groups,  and $B$ and $D$ be ICC hyperbolic groups. Assume that $G\in\mathcal W\mathcal R(A,B)$ and $H\in \mathcal{W}\mathcal{R}(C,D)$ are measure equivalent groups. Then the groups $A^{(B)}$ and $C^{(D)}$ are measure equivalent.
\end{theorem}

\item We first use the following theorem.

\begin{theorem}\label{thm:MSinfiniteICCsum}
Suppose $G _i$, $i\in I$, and $H _j$, $j\in J$, are ICC groups in the class $\mathcal{C}$, where $I,J$ are countable. If $G \coloneqq \bigoplus _{i\in I}G _i$ and $H \coloneqq \bigoplus _{j\in J} H _j$ are measure equivalent then $|I|=|J|$ and there exists a bijection $t:I\rightarrow J$ such that $G _i$ is measure equivalent with $H_{t(i)}$ for all $i\in I$.
\end{theorem}
\end{enumerate}
Then the ingredients are combined as follows. Let $\{A_k\}_{k\geq 1}$ be as in (1). For $x\in\{0,1\}^{\mathbb N}$ (viewed as a subset of $\mathbb N$), set $D_x=\bigoplus_{k\in x}A_k$. By (2) there exists a property (T) group $G_x\in\mathcal W\mathcal R(D_x,B)$, and it is torsion-free since it is built from the torsion-free groups $\{A_k\}$ and $B$. If $G_x$ and $G_y$ are measure equivalent, then by the theorem above one gets that $D_x^{(\mathbb N)}\cong\oplus_{k\in x}A_k^{(\mathbb N)}$ and $D_y^{(\mathbb N)}\cong\oplus_{k\in y}A_k^{(\mathbb N)}$ are measure equivalent. Using the defining properties of the sequence $\{A_k\}$ from (1), the theorem above forces $x=y$, yielding a continuum family of pairwise non-measure equivalent groups $\{G_x\}$ as in the main theorem.

theorem.content:
\label{global_existence} For $d=2, 3$,
there exists a diffeomorphism $\xi_0: \mathbb{R}^d \to \mathbb{R}^d$  {and a small constant $\varepsilon>0$} such that if the initial data $(\rho_0, u_0, F_0)$, with
$(\rho_0(x) -1, u_0(x) -x, F_0(x) -I)\in H^3_x(\mathbb{R}^d)$, satisfies
{\begin{eqnarray*}\label{decay_estiwmates_1}
    \begin{cases}
      \rho_0(x) \mathrm{det}F_0(x)=1,\,\,\,\,F_0(x) = \nabla_y \xi_0(y),\,\,\,\,  y =\xi_0^{-1}(x), \ \forall x\in\mathbb{R}^d, \\[2mm]
      \|\rho_0(x) -1\|_{H^3_x} + \|u_0(x) -x\|_{H^3_x} + \|F_0(x) -I\|_{H^3_x} + \|\xi_0^{-1}(x)-x\|_{H^4_x}\le \varepsilon,
    \end{cases}
\end{eqnarray*}}then the Cauchy problem \eqref{elasticity_equation_1} admits a unique global strong solution 
$(\rho, u, F)$ such that $\big(\rho(x,t) -\frac{1}{(1+t)^d}, u(x,t)-\frac{x}{1+t}, F(x,t) -(1+t)I\big) \in C\big([0, \infty); H^3_x(\mathbb{R}^d)\big)$. Moreover, $(\rho, u, F)$ satisfies the following estimates:
\begin{eqnarray*}\label{decay_estimates_1}
  \begin{cases}
    \|\nabla_x^{i}(\rho(x,t) -\frac{1}{(1+t)^d})\|_{L^2_x}\le C\varepsilon(1+t)^{-\frac{d}{2}-\frac{1}{2}-i},\\[1mm]
     \|\nabla_x^{i}\big(u(x,t)-\frac{x}{1+t}, F(x,t) -(1+t)I\big)\|_{L^2_x} \le C\varepsilon(1+t)^{\frac{d}{2}+\frac{1}{2}-i}
  \end{cases}
\end{eqnarray*}for all $t>0$ and $i=0,1,2,3$, {where $C$ is a generic positive constant depending on some known constants but independent of $\varepsilon$ and $t$.}

ref_dict.global_existence_Lagrangian:
\begin{theorem}\label{global_existence_Lagrangian}
       For $d=2,3$,  there exists a sufficiently small  constant $\varepsilon_1>0$ such that the Cauchy problem \eqref{compressible_elasticity_equation_3} admits a global strong solution 
       $(V,\xi)$ satisfying $(V(y,t)-y, \xi(y,t) - (1+t)y)$ in $C\big([0, \infty); H^3_y(\mathbb{R}^d)\times H^4_y(\mathbb{R}^d)\big)$,  provided that
          \begin{equation*} \label{initial_assumption_Lagrangian}
              \begin{split}
              \|V_0(y)-y\|_{H^3_y} + \|\xi_0(y) -y\|_{H^4_y}\le \varepsilon_1.
              \end{split}
          \end{equation*}
Moreover, $(V,\xi)$ satisfies the following estimates:
\begin{eqnarray}\label{decay_estimates_Lagrangian}
  \begin{cases}
    \|V(y,t) -y\|_{H^3_y} \le C\varepsilon_1(1+t)^{\frac{1}{2}},\\[1mm]
    \|\xi(y,t) - (1+t)y\|_{H^3_y} \le C\varepsilon_1(1+t)^{\frac{3}{2}},\\[1mm]
     \|\nabla_y \xi(y,t) - (1+t)I\|_{H^3_y} \le C\varepsilon_1(1+t)^{\frac{1}{2}}
  \end{cases}
\end{eqnarray}
for all $t>0$, where $C$ is a generic positive constant depending on some known constants but independent of $\varepsilon_1$ and $t$.
\end{theorem}

