{With the absence of the elastic stress $\textrm{div}(\rho FF^\top)$ in the momentum equation, the system \eqref{elasticity_equation_1} becomes a degenerate system whenever the physical vacuum is present. Indeed, by globally solving a Hamiltonian system of ordinary differential equations for the deformation gradient, the free boundary problem of the three dimensional compressible and incompressible Euler equations with an affine initial condition and physical vacuum boundary condition is constructed in \cite{Sideris_2017}. Hadzic and Jang in \cite{Hadzic_2018} has verified the global-in-time nonlinear stability in Sobolev spaces of the affine solutions to compressible Euler equations for $\gamma\in(1,\frac53]$, and the full range of $\gamma\in (1,\infty)$ is studied in \cite{Shkoller_2019}. Note that the determinant of deformation gradients of the affine solution in \cite{Sideris_2017, Hadzic_2018, Shkoller_2019} grows at the maximal rate of $(1+t)^3$, as $t\rightarrow\infty$. In this sense, Theorem \ref{global_existence} would be regarded as the asymptotic nonlinear stability of the affine solution in \cite{Sideris_2017, Hadzic_2018, Shkoller_2019} when the elastic stress is taken into consideration in the momentum equation.

\section{Global well-posedness in Eulerian coordinate}\label{section_4}
This section is devoted to the completion of the proof of Theorem \ref{global_existence}. Throughout this section, C denotes a generic positive constant that depends on
some known constants, but independent of $\varepsilon$, $\varepsilon_1$ and $t$.
\subsection{Regularity estimates}\label{subsection_7}
With Theorem \ref{global_existence_Lagrangian}, we are going to construct a global-in-time solution to the system
\eqref{elasticity_equation_1} in Eulerian coordinate. For any $(u_0, \xi_0)$ given in Theorem \ref{global_existence}, we define $V_0$ as follows
 \begin{equation}\label{V_0}
 V_0(y)=u_0(\xi_0(y)).
\end{equation}
{Combining \eqref{V_0} with the assumptions of Theorem \ref{global_existence}, we deduce
\begin{equation*}\label{1}
 \begin{split}
 \|V_0(y)-y\|_{H^3_y} + \|\xi_0(y) -y\|_{H^4_y}\le C\varepsilon + C\varepsilon^3 \le C\varepsilon.
 \end{split}
\end{equation*}
Then, letting $\varepsilon = \frac{\varepsilon_1}{C}$ yields
\begin{equation}\label{2}
 \begin{split}
 \|V_0(y)-y\|_{H^3_y} + \|\xi_0(y) -y\|_{H^4_y}\le \varepsilon_1.
 \end{split}
\end{equation}
Substituting $V_0(y)$ and $\xi_0(y)$, that satisfy \eqref{V_0} and \eqref{2}, into Theorem \ref{global_existence_Lagrangian}, we obtain the existence of a unique global solution $(\xi,V)$ to the system \eqref{compressible_elasticity_equation_3}.

For the second term, we similarly obtain
 \begin{equation}\label{Euler_part_17}
 \begin{split}
 &\int_{\mathbb{R}^d} \Big|{\rm adj}[\nabla_y \xi] - (1+t)^{d-1}I\Big|^2\,dy\\ &\le C \Big(\|\nabla_y \xi\|_{L^\infty_y}^{2(d-2)} + (1+t)^{2(d-2)}\Big)\|\nabla_y \xi -(1+t)I\|_{L^2_y}^2\\ & \le C\varepsilon^2 (1+t)^{2d-3}.
 \end{split}
 \end{equation}
Substituting \eqref{Euler_part_16} and \eqref{Euler_part_17} into \eqref{Euler_part_14} and \eqref{Euler_part_15} gives
 \begin{equation}\label{Euler_part_18}
 \begin{split}
 \|\rho(x,t) -\frac{1}{(1+t)^d}\|_{L^2_x}^2 \le C\varepsilon^2 (1+t)^{-d-1}.
 \end{split}
 \end{equation}
 Next, we consider the estimate of $\|\nabla \big(\rho(x,t) -\frac{1}{(1+t)^d}\big)\|_{L^2_x}$ and $\|\nabla^2 \big(\rho(x,t) -\frac{1}{(1+t)^d}\big)\|_{L^2_x}$. Combining \eqref{decay_estimates_Lagrangian}, \eqref{Euler_part_4_1}, \eqref{Euler_part_nn_2}-\eqref{Euler_part_nn_3}, {$\varepsilon = \frac{\varepsilon_1}{C}$} with $\nabla_y B_{ij}= -B_{il}\partial_l\nabla_y\xi_{k}B_{kj}$ and $\nabla_y \mathcal{J}= \mathcal{J} B_{ij}\partial_j\nabla_y \xi_{i}$ in \eqref{flow_map_5_1}, we have
 \begin{equation}\label{Euler_part_10}
 \begin{split}
 &\|\nabla_x \big(\rho(x,t) -\frac{1}{(1+t)^d}\big)\|_{L^2_x}^2 \\ &\le C(1+t)^d \int_{\mathbb{R}^d} |B\nabla_y(\mathcal{J}^{-1})|^2\,dy\\
 &\le C(1+t)^d\int_{\mathbb{R}^d} |B\mathcal{J}^{-2}\nabla_y\mathcal{J}|^2\,dy\\
 &\le C(1+t)^d|B|^4 |\mathcal{J}|^{-2} \int_{\mathbb{R}^d} |\nabla^2_y \xi|^2\,dy\\
 &\le C \varepsilon^2 (1+t)^{-d-3}
 \end{split}
 \end{equation}
 and
 \begin{equation}\label{Euler_part_11}
 \begin{split}
 &\|\nabla^2_x \big(\rho(x,t) -\frac{1}{(1+t)^d}\big)\|_{L^2_x}^2\\ 
 &\le C(1+t)^d\int_{\mathbb{R}^d} \big|B\nabla_y[B\nabla_y(\mathcal{J}^{-1})]\big|^2\,dy \\
 &\le C(1+t)^d\Big[\int_{\mathbb{R}^d} |B\nabla_y B\mathcal{J}^{-2}\nabla_y\mathcal{J}|^2 \,dy + \int_{\mathbb{R}^d} |BB \mathcal{J}^{-3}\nabla_y\mathcal{J}\nabla_y\mathcal{J}|^2 \,dy\\ 
 & +\int_{\mathbb{R}^d} |BB\mathcal{J}^{-2}\nabla_y^2\mathcal{J}|^2 \,dy\Big]\\
 &\le C \varepsilon^2 (1+t)^{-d-6} + C \varepsilon^2 (1+t)^{-d-6} +C \varepsilon^2 (1+t)^{-d-5} \\ 
 &\le C \varepsilon^2 (1+t)^{-d-5}.
 \end{split}
 \end{equation}
 Finally, we estimate $\|\nabla^3_x \big(\rho(x,t) -\frac{1}{(1+t)^d}\big)\|_{L^2_x}$. Combining \eqref{decay_estimates_Lagrangian}, \eqref{Euler_part_4_1}, \eqref{Euler_part_nn_4}, $\varepsilon = \frac{\varepsilon_1}{C}$ with $\nabla_y B_{ij}= -B_{il}\partial_l\nabla_y\xi_{k}B_{kj}$ and $\nabla_y \mathcal{J}= \mathcal{J} B_{ij}\partial_j\nabla_y \xi_{i}$ in \eqref{flow_map_5_1}, we have
 \begin{align}\label{Euler_part_11_1}
 &\notag\|\nabla^3_x \big(\rho(x,t) -\frac{1}{(1+t)^d}\big)\|_{L^2_x}^2\\ \notag &\le C(1+t)^d\int_{\mathbb{R}^d} \Big|B\nabla_y\big\{B\nabla_y\big[B\nabla_y(\mathcal{J}^{-1})\big]\big\}\Big|^2\,dy\\ &
 \le C(1+t)^d\Big[\int_{\mathbb{R}^d} |B\nabla_y B\nabla_y B\mathcal{J}^{-2}\nabla_y\mathcal{J}|^2 \,dy + \int_{\mathbb{R}^d} |BB \nabla_y^2 B\mathcal{J}^{-2}\nabla_y\mathcal{J}|^2 \,dy\notag\\ & +\int_{\mathbb{R}^d} |BB\nabla_y B\mathcal{J}^{-3}\nabla_y\mathcal{J}\nabla_y\mathcal{J}|^2 \,dy +\int_{\mathbb{R}^d} |BB\nabla_y B\mathcal{J}^{-2}\nabla_y^2\mathcal{J}|^2 \,dy\\ & +\int_{\mathbb{R}^d} |BBB\mathcal{J}^{-4}\nabla_y\mathcal{J}\nabla_y\mathcal{J}\nabla_y\mathcal{J}|^2 \,dy +\int_{\mathbb{R}^d} |BBB\mathcal{J}^{-3}\nabla_y\mathcal{J}\nabla_y^2\mathcal{J}|^2 \,dy\notag\\ & \notag +\int_{\mathbb{R}^d} |BBB\mathcal{J}^{-2}\nabla_y^3\mathcal{J}|^2\,dy\Big]\\ &\notag
 \le\, C \varepsilon^2 (1+t)^{-d-9} + C \varepsilon^2 (1+t)^{-d-8} + C \varepsilon^2 (1+t)^{-d-9}+ C \varepsilon^2 (1+t)^{-d-8} \notag \\ &+ C \varepsilon^2 (1+t)^{-d-9} + C \varepsilon^2 (1+t)^{-d-8} + C \varepsilon^2 (1+t)^{-d-7}\notag\\ &\le \,C \varepsilon^2 (1+t)^{-d-7}.\notag
\end{align}
 From \eqref{Euler_part_ww_1}-\eqref{Euler_part_ww_4}, \eqref{Euler_part_ee_1}-\eqref{Euler_part_ee_4}, and \eqref{Euler_part_18}-\eqref{Euler_part_11_1}, we conclude that
 \begin{eqnarray*}\label{decay_1}
 \begin{cases}
 \|\nabla_x^i \big(\rho(x,t) -\frac{1}{(1+t)^d}\big)\|_{L^2_x}\le C\varepsilon (1+t)^{-\frac{d}{2}-\frac{1}{2}-i},\\[1mm]
 \|\nabla_x^i\big(u(x,t)-\frac{x}{1+t}, F(x,t) -(1+t)I\big)\|_{L^2_x} \le C\varepsilon(1+t)^{\frac{d}{2}+\frac{1}{2}-i}
 \end{cases}
 \end{eqnarray*}
 for all $t \ge 0$ and $i=0,1,2,3$. The proof of Theorem \ref{global_existence} is complete.

