theorem.content:
[$=$\,Theorem~\ref{thm:QK-Whitney_A}\,$+$\,Theorem~\ref{thm:QK-Whitney_B}] \label{ithm:QK-Whitney}
\begin{enu}
\item In $QK_{T}(\FlC{n})[y]$, for $1 \le k \le n$, we have 
\begin{equation} \label{eq:QK-Whitney_1_intro}
\lambda_{y}(\CS_{k-1}) \star \lambda_{y}(\CS_{k}/\CS_{k-1}) = \lambda_{y}(\CS_{k}) - y \frac{Q_{k-1}}{1-Q_{k-1}} [\CS_{k}/\CS_{k-1}] \star (\lambda_{y}(\CS_{k-1}) - \lambda_{y}(\CS_{k-2})). 
\end{equation}

\item In $QK_{T}(\FlC{n})[y]$, for $1 \le k \le n$, we have
\begin{equation} \label{eq:QK-Whitney_2_intro}
\lambda_{y}(\CS_{k-1}^{\vee}) \star \lambda_{y}((\CS_{k}/\CS_{k-1})^{\vee}) = \lambda_{y}(\CS_{k}^{\vee}) - y \frac{Q_{k-1}}{1-Q_{k-1}} [(\CS_{k}/\CS_{k-1})^{\vee}] \star (\lambda_{y}(\CS_{k-1}^{\vee}) - \lambda_{y}(\CS_{k-2}^{\vee})). 
\end{equation}

\item In $QK_{T}(\FlC{n})[y]$, we have 
\begin{equation} \label{eq:QK-Whitney_3_intro}
\begin{split}
& \lambda_{y}(\CS_{n}) \star \lambda_{y}(\CS_{n}^{\vee}) = \lambda_{y}(\underline{\BC}^{2n}) \\ 
& \qquad - y^{2} \sum_{p=1}^{n} \frac{Q_{p} \cdots Q_{n}}{1-Q_{p-1}} (\lambda_{y}(\CS_{p-1}) - Q_{p-1} \lambda_{y}(\CS_{p-2})) \star (\lambda_{y}(\CS_{p-1}^{\vee}) - Q_{p-1} \lambda_{y}(\CS_{p-2}^{\vee})). 
\end{split}
\end{equation}

\end{enu}

ref_dict.thm:QK-Whitney_B:
\begin{thm} \label{thm:QK-Whitney_B}
In $QK_{T}(\FlC{n})[y]$, we have 
\begin{equation} \label{eq:QK-Whitney_3}
\begin{split}
& \lambda_{y}(\CS_{n}) \star \lambda_{y}(\CS_{n}^{\vee}) = \lambda_{y}(\udBC^{2n}) \\ 
& \qquad - y^{2} \sum_{p=1}^{n} \frac{Q_{p} \cdots Q_{n}}{1-Q_{p-1}} (\lambda_{y}(\CS_{p-1}) - Q_{p-1} \lambda_{y}(\CS_{p-2})) \star (\lambda_{y}(\CS_{p-1}^{\vee}) - Q_{p-1} \lambda_{y}(\CS_{p-2}^{\vee})). 
\end{split}
\end{equation}
\end{thm}

ref_dict.thm:Whitney_presentation:
\begin{thm} \label{thm:Whitney_presentation}
There exists an $R(T)$-algebra isomorphism $R_{Q}^{\SW}/I_{Q}^{\SW} \xrightarrow{\sim} QK_{T}(\FlC{n})$ such that 
\begin{align}
F_{d}^{k} & \mapsto \left[ \extprod^{d} \CS_{k} \right] & & \text{for $1 \le k \le n$ and $1 \le d \le k$}, \\ 
G_{d}^{k} & \mapsto \left[ \extprod^{d} \CS_{k}^{\vee} \right] & & \text{for $1 \le k \le n$ and $1 \le d \le k$}, \\ 
x_{j} & \mapsto [\CS_{j}/\CS_{j-1}] & & \text{for $1 \le j \le n$}, \\ 
y_{j} & \mapsto [(\CS_{j}/\CS_{j-1})^{\vee}] & & \text{for $1 \le j \le n$}. 
\end{align}
\end{thm}

