\mathcal{S}_\mu = \bigcup_{k=1}^n \mathcal{S}_\mu^k,
\qquad\text{where} \qquad
\mathcal{S}_\mu^k \coloneqq \left \{x \in \mathcal{S}_\mu \colon \dim D_x=k \right \}.
\end{equation}
Do these $\mathcal{S}_\mu^k$ enjoy finer rectifiability properties?
\end{itemize}

The main result of this note provides an answer to these questions.

\begin{lemma}\label{lmm:0-hom}
Let $\mu$ be a signed Radon measure on $\mathbb{R}^n$ and let $\mu_x \neq 0$ be the unique blow-up of $\mu$ at $x \in \mathcal{S}_\mu$. Then there exists $\alpha=\alpha(x)\geq 0$ such that $\mu_x$ and $|\mu_x|$ are $(\alpha-n)$-homogeneous,\footnote{According to this definition, the measure induced by a $p$-homogenous locally integrable function $f$, with respect to the Lebesgue measure, is $p$-homogeneous as well.} namely
\begin{equation}\label{eq:hom_blow-up}
(\tau_{0,\lambda})_\# \mu_x=\lambda^\alpha \mu_x,
\quad
(\tau_{0,\lambda})_\# |\mu_x|=\lambda^\alpha |\mu_x|
\qquad
\forall \lambda>0.
\end{equation}
For $\mu_x$, and more generally for every $(\alpha-n)$-homogeneous Radon measure, the set
\begin{equation}
C_x\coloneqq \left \{ y \in \mathbb{R}^n \colon (\tau_{y,\lambda})_\# \mu_x=\lambda^\alpha (\tau_{y,1})_\# \mu_x \,\,\,\,\forall \lambda>0 \right \}
\end{equation}
coincides with the invariant subspace $D_x$ of $\mu_x$, that is
\begin{equation}
D_x \coloneqq \left \{ y \in \mathbb{R}^n \colon (\tau_{y,1})_\# \mu_x= \mu_x \right \}.
\end{equation}
Moreover $D_x$ is a linear subspace of $\mathbb{R}^n$ and, provided $\mu_x \neq 0$, it holds $\dim D_x \leq \alpha$.
\end{lemma}

This problem has already received some attention: in \cite{delnin21} it is proved that, for a given $u \in L^1_{\text{loc}}(\mathbb{R}^n)$, the set $\Sigma_u$ of points $x$ where $\frac{1}{r^n}u \left (\frac{\cdot-x}{r} \right )$ converges, in the $L^1_{\mathrm{loc}}$-topology, to a non-constant function can be covered by a countable union of $(n-1)$-dimensional Lipschitz graphs. 
\begin{itemize}
\item The results in \cite{delnin21} rely on the fact that the measure $\mu$ is induced by a $L^1_{\mathrm{loc}}$ function $u$ and that the rescalings converge in the $L^1_{\mathrm{loc}}$-topology, while in $\mathcal{S}_\mu$ the convergence is intended in the weak*-topology of Radon measures. Thus the subset of $\mathcal{S}_\mu$ where the unique blow-up of $u$ is not a constant function can be larger than $\Sigma_u$.
Is this set rectifiable as well? What can be said if $\mu$ is a general Radon measure?

The main result of this note provides an answer to these questions.

The idea of the proof is that, for every $x \in \mathcal{S}_\mu^k$, there is a radius $r>0$ for which the points in $\mathcal{S}_\mu^k \cap B_r(x)$ with similar properties are contained in a cone $x+C$ around $x+D_x$. Otherwise, by contradiction, one can find a sequence of such points $y_j \notin x+C$ with $r_j=|x-y_j| \to 0$ and such that the measures $c_j \mu_{y_j}$ and $\mu_{y_j,r_j}$ are as close as we want. Now, on one hand $c_j\mu_{y_j}$ converges to a measure $\nu$ whose invariant subspace is close to $D_x$; on the other hand $\mu_{y_j,r_j}$, being translations of $\mu_{x,r_j}$ with respect to points outside $C$, converge to a translation of $\mu_x$ whose invariant subspace is not contained in $C$, contradicting the closeness of $c_j\mu_{y_j}$ and $\mu_{y_j,r_j}$.

\begin{corollario}\label{cor:rectif_criterion}
Let $\mu$ be a signed Radon measure on $\mathbb{R}^n$ and $k \in \{0,1,\dots,n\}$. Let us assume that, for $|\mu|$-a.e.\ $x \in \mathbb{R}^n$, there exists a Radon measure $\nu_x$ whose invariant linear subspace $V_x$ is $k$-dimensional and with the property that, for every sequence $r_j \to 0^+$ there are a subsequence, not relabeled, and a constant $c\neq 0$ such that
\begin{equation}
\frac{1}{r_j^k} (\tau_{x,r_j})_\# \mu
\overset{\ast}{\rightharpoonup} c \nu_x.
\end{equation}
Then $\mu$ is $k$-rectifiable: there exists a signed function $\theta \in L^1_{\mathrm{loc}}(\mathcal{S}_\mu^k,\mathcal{H}^k)$ such that \mbox{$\mu= \theta \mathcal{H}^k \llcorner \mathcal{S}_\mu^k$,} where $\mathcal{S}_\mu^k$ is defined in \eqref{eq:def_s_mu_k}.
\end{corollario}

\begin{corollario}\label{cor:almost_everywhere_rect}
Let $\mu$ be a signed Radon measure on $\mathbb{R}^n$ and $k \in \{0,1,\dots,n\}$. Then, for $|\mu|$-a.e.\ $x \in \mathcal{S}_\mu^k$, the unique blow-up of $\mu$ at $x$ is a multiple of $\mathcal{H}^k\llcorner D_x$.
\end{corollario}

\begin{lemma}\label{lmm:0-hom}
Let $\mu$ be a signed Radon measure on $\mathbb{R}^n$ and let $\mu_x \neq 0$ be the unique blow-up of $\mu$ at $x \in \mathcal{S}_\mu$. Then there exists $\alpha=\alpha(x)\geq 0$ such that $\mu_x$ and $|\mu_x|$ are $(\alpha-n)$-homogeneous,\footnote{According to this definition, the measure induced by a $p$-homogenous locally integrable function $f$, with respect to the Lebesgue measure, is $p$-homogeneous as well.} namely
\begin{equation}\label{eq:hom_blow-up}
(\tau_{0,\lambda})_\# \mu_x=\lambda^\alpha \mu_x,
\quad
(\tau_{0,\lambda})_\# |\mu_x|=\lambda^\alpha |\mu_x|
\qquad
\forall \lambda>0.
\end{equation}
For $\mu_x$, and more generally for every $(\alpha-n)$-homogeneous Radon measure, the set
\begin{equation}
C_x\coloneqq \left \{ y \in \mathbb{R}^n \colon (\tau_{y,\lambda})_\# \mu_x=\lambda^\alpha (\tau_{y,1})_\# \mu_x \,\,\,\,\forall \lambda>0 \right \}
\end{equation}
coincides with the invariant subspace $D_x$ of $\mu_x$, that is
\begin{equation}
D_x \coloneqq \left \{ y \in \mathbb{R}^n \colon (\tau_{y,1})_\# \mu_x= \mu_x \right \}.
\end{equation}
Moreover $D_x$ is a linear subspace of $\mathbb{R}^n$ and, provided $\mu_x \neq 0$, it holds $\dim D_x \leq \alpha$.
\end{lemma}

\begin{proof}[Proof of Theorem \ref{thm:main}]
The statement is trivial for $k=n$, thus we assume $k \in \{0,1,\dots,n-1\}$ be fixed throughout the proof.
Let us moreover fix $\gamma \in \left (0,\frac{1}{16}\right )$. It is possible to choose a finite number $m$ of $k$-dimensional linear subspaces $\{V_\ell\}_{\ell=1}^m$ such that every $k$-dimensional linear subspace $V$ is contained in $\overline{C(0,V_\ell,\gamma)}$ for some $\ell \in \{1,\dots,m\}$. For every $\ell \in \{1,\dots,m\}$ and every $i \in \mathbb{N}$, we define the set
\begin{equation}
E_{\ell,i} \coloneqq \left \{ x \in \mathcal{S}^k \colon D_x \subset \overline{C(0,V_\ell,\gamma)},\,\,\, \alpha(x) \leq i,\,\,\, \eta(x)\geq \frac{1}{i},\,\,\, d(c\mu_{x},\omega)\geq \frac{1}{i} \,\,\,\forall |c| \in \left [\frac{1}{i},1 \right ],\, \forall\omega \in \operatorname{Hom}_{k+1}^i \right \},
\end{equation}
where $D_x$ and $\alpha(x)$ are respectively the invariant subspace and the homogeneity exponent of $\mu_x$ given by Lemma \ref{lmm:0-hom}, $\eta=\eta(x)$ is given by Lemma \ref{lmm:lower_bound_mass_blow-up}, while $d$ and $\operatorname{Hom}_{k+1}^i$ are respectively the distance and the set of $(\alpha-n)$-homogeneous measures described in Section \ref{sec:notations}.
Since $\mathcal{S}^k= \bigcup_{i \in \mathbb{N}}\bigcup_{\ell=1}^m E_{i,\ell}$, it is enough to prove that each $E_{i,\ell}$ can be covered by a countable union of Lipschitz graphs.

Let us fix $i \in \mathbb{N}$ and $\ell \in \{1,\dots,m\}$. 
Then fix the value $\varepsilon$ given by Lemma \ref{lmm:too_close} for $\beta=i$, $\delta=\frac{1}{i}$, $M=i \cdot 2^\alpha$ and, for every $\rho>0$, define the set
\begin{equation}
E_{i,\ell,\rho} \coloneqq
\left \{x \in E_{i,\ell} \colon \inf_{|c| \in [\eta,1]}d(\mu_{x,r},c\mu_x)< \varepsilon \,\,\,\forall r \in (0,\rho) \right \}.
\end{equation}
If $x \in E_{i,\ell}$, then it belongs to $E_{i,\ell,\rho}$ for some $\rho>0$, because the existence of a sequence $r_j \to 0$ such that $d(\mu_{x,r_j},c\mu_x) \geq \varepsilon$ for every $j \in \mathbb{N}$ and every $|c| \in [\eta,1]$ would contradict $x \in \mathcal{S}$. Therefore
\begin{equation}
E_{i,\ell} = \bigcup_{\rho \in \mathbb{Q} \cap (0,+\infty)} E_{i,\ell,\rho}
\end{equation}
and it suffice to prove that, for a fixed $\rho>0$, the set $E_{i,\ell,\rho}$ can be covered with a countable union of Lipschitz graphs.
In order to do so, we claim that, for every $x \in E_{i,\ell,\rho}$, there exists $r>0$ such that
\begin{equation}\label{eq:outside_cones}
E_{i,\ell,\rho} \cap B_{r}(x) \setminus C(x,D_x,3\gamma)= \{x\}.
\end{equation}
Let us fix $x\in E_{i,\ell,\rho}$, let $\mu_x$ be $(\alpha-n)$-homogeneous and let us assume, toward a contradiction, that for every $j \in \mathbb{N}$ there exists 
\begin{equation}\label{eq:y_j_final}
y_j \in E_{i,\ell,\rho} \cap \overline{B_{\frac{r_j}{2}}(x)} \setminus\Big( B_{\frac{r_j}{4}}(x) \cup C(x,D_x,3\gamma) \Big),
\end{equation}
for some $r_j \leq \rho$ such that $r_j \downarrow 0$. This in particular implies the existence of constants $c_j$ with $|c_j| \in \left [\frac{1}{i},1 \right ]$ such that
\begin{equation}\label{eq:distance_muj}
d( c_j\mu_{y_j}, \mu_{y_j,r_j})< \varepsilon
\qquad
\forall j \in \mathbb{N}.
\end{equation}
Up to selecting a non relabeled subsequence and without loss of generality, we can assume $c_j>0$ and that $\mu_{x,r_j} \overset{\ast}{\rightharpoonup} c\mu_x$ for some $c \in \left [\frac{1}{i},1 \right ]$.
We now analyze the weak*-limit (up to a suitable subsequence) of the two sequences of measures in \eqref{eq:distance_muj}.

selected.post_theorem_intro_text:
The idea of the proof is that, for every $x \in \mathcal{S}_\mu^k$, there is a radius $r>0$ for which the points in $\mathcal{S}_\mu^k \cap B_r(x)$ with similar properties are contained in a cone $x+C$ around $x+D_x$. Otherwise, by contradiction, one can find a sequence of such points $y_j \notin x+C$ with $r_j=|x-y_j| \to 0$ and such that the measures $c_j \mu_{y_j}$ and $\mu_{y_j,r_j}$ are as close as we want. Now, on one hand $c_j\mu_{y_j}$ converges to a measure $\nu$ whose invariant subspace is close to $D_x$; on the other hand $\mu_{y_j,r_j}$, being translations of $\mu_{x,r_j}$ with respect to points outside $C$, converge to a translation of $\mu_x$ whose invariant subspace is not contained in $C$, contradicting the closeness of $c_j\mu_{y_j}$ and $\mu_{y_j,r_j}$.

\medskip

A first outcome of Theorem \ref{thm:main} is a rectifiability criterion for signed Radon measures in terms of their blow-ups which, to the best of our knowledge, is new.

\begin{corollario}\label{cor:rectif_criterion}
Let $\mu$ be a signed Radon measure on $\mathbb{R}^n$ and $k \in \{0,1,\dots,n\}$. Let us assume that, for $|\mu|$-a.e.\ $x \in \mathbb{R}^n$, there exists a Radon measure $\nu_x$ whose invariant linear subspace $V_x$ is $k$-dimensional and with the property that, for every sequence $r_j \to 0^+$ there are a subsequence, not relabeled, and a constant $c\neq 0$ such that
\begin{equation}
\frac{1}{r_j^k}  (\tau_{x,r_j})_\# \mu
\overset{\ast}{\rightharpoonup} c \nu_x.
\end{equation}
Then $\mu$ is $k$-rectifiable: there exists a signed function $\theta \in L^1_{\mathrm{loc}}(\mathcal{S}_\mu^k,\mathcal{H}^k)$ such that \mbox{$\mu= \theta \mathcal{H}^k \llcorner \mathcal{S}_\mu^k$,} where $\mathcal{S}_\mu^k$ is defined in \eqref{eq:def_s_mu_k}.
\end{corollario}

The above result extends to signed Radon measures the well-known criterion for positive ones, see for instance \cite[Theorem 11.8]{simonlectures83}, where one usually sets $\nu_x=\theta_0 \mathcal{H}^k \llcorner V_x$ for some $k$-dimensional linear subspace $V_x$ and assumes the existence of the limit $r^{-k}(\tau_{x,r_j})_\# \mu \overset{\ast}{\rightharpoonup} \theta_0 \mathcal{H}^k \llcorner V_x$ as $r \to 0^+$.

We point out that Corollary \ref{cor:rectif_criterion} cannot be trivially deduced from the corresponding result for positive measures, since the fact that $\mu$ has a certain blow-up at a point does not provide any suitable information on the blow-ups of $|\mu|$ at the same point, not even their uniqueness; nor does it appear that the classical proof of \cite[Theorem 11.8]{simonlectures83} can be readily adapted to the case of signed measures.

\medskip

A further consequence of Theorem \ref{thm:main} is the following extension of \cite[Theorem 3.2]{mattila_unique05} to signed Radon measures. It is based on the intuitive idea that, since each $\mathcal{S}_{\mu}^k$ is $k$-rectifiable, it is reasonable to expect that its subset of points where the blow-up of $\mu$ is more diffused than a $k$-dimensional measure is $|\mu|$-negligible.

\begin{corollario}\label{cor:almost_everywhere_rect}
Let $\mu$ be a signed Radon measure on $\mathbb{R}^n$ and $k \in \{0,1,\dots,n\}$. Then, for $|\mu|$-a.e.\ $x \in \mathcal{S}_\mu^k$, the unique blow-up of $\mu$ at $x$ is a multiple of $\mathcal{H}^k\llcorner D_x$.
\end{corollario}

We conclude this introduction with a comment on the definition of unique blow-up at a point.
As already said above, we say that $\mu_x$ is the unique blow-up of $\mu$ at $x \in \operatorname{supp}\mu$ if, for every sequence $r_j \to 0$, \emph{there exists} a subsequence for which \eqref{eq:def-unique_blowup} holds true. This differs from the definition used in \cite{mattila_unique05} for positive Radon measures, where one does not require the convergence of a subsequence for every choice of $\{r_j\}_j$: according to \cite{mattila_unique05}, one says that  $\mu$ has unique blow-up at $x \in \mathbb{R}$ if there exists $\nu$ such that any non-trivial weak*-limit (in case it exists) of $c_j (\tau_{x,r_j})_\# \mu$, where $c_j>0$ and $r_j \to 0^+$, is of the form $c\nu$ for some $c>0$. 

\cite[Lemma 2.5]{mattila_unique05} shows, provided $\mu$ is positive, that this condition actually implies $\mu_{x,r} \overset{\ast}{\rightharpoonup} c\mu_x$ as $r \to 0$ and, subsequently, our definition (they are actually equivalent).
However, this does not hold in the case of signed Radon measures: let us consider two sequences of positive real numbers $a_j, \rho_j$ such that
\begin{equation}
\lim_{j \to +\infty} \frac{1}{a_j} \sum_{i=j+1}^{+\infty} a_i = 0,
\qquad
\lim_{j \to +\infty} \frac{\rho_{j+1}}{\rho_j}=0.
\end{equation}
Then the Radon measure on $\mathbb{R}$ defined as
\begin{equation}
\mu \coloneqq \sum_{j \in \mathbb{N}} a_j\left ( \delta_{2\rho_j + \rho_j^2} - \delta_{2\rho_j - \rho_j^2} \right )
\end{equation}
has the null measure as unique blow-up at $x=0$ in the sense of \cite{mattila_unique05}, but $\mu_{0,\rho_j} =\frac{1}{|\mu|(B_{\rho_j}(0))} (\tau_{0,\rho_j})_\# \mu $ has no converging subsequences because $|\mu_{x,\rho_j}|\big(B_2(0)\big) \to +\infty$ as $j\to +\infty$.

