Namely, $\Bac_\varepsilon$ happens if there are two continuous curves $\gamma^1,\gamma^2:[0,1]\to\mathbbm{C}$ such that $\gamma^1[0,1]\cap\gamma^2[0,1]=\emptyset$, $\gamma^i[0,1]\subset B[0,\tau_{\mathbbm{D}}]$, $\gamma^i(0)\in\varepsilon\mathbbm{S}^1$, and $\gamma^i(1)\in\frac{1}{2}\mathbbm{S}^1$ for $i=1,2$. Using terminology from percolation, we call $\Bac_\varepsilon$ the \emph{backbone event} for the Brownian trajectory $B[0,\tau_\mathbbm{D}]$.

The main result in this paper is the following iterated logarithmic decay for the probability $\mathbbm{P}[\Bac_\varepsilon]$.

The main result in this paper is the following iterated logarithmic decay for the probability $\P[\Bac_\varepsilon]$.

Let $f$ be the conformal map from $D(\ell_1)$ to $\D$ with $f(0)=0$, $f'(0)>0$ and let $\rho=f(\wt\ell_1)$. Note that $\CR(\rho,0)=\frac{\CR(\wt\ell_1,0)}{\CR(\ell_1,0)}$. 
The main result of this section is the following exact law of $\CR(\rho,0)$, which is crucial to the final proof of Theorem~\ref{thm:backbone} in Section~\ref{section-backbone-2}.
\begin{proposition}
\label{prop-cr-rho}
For $\lambda\ge0$, we have
\begin{equation}\label{eq:cr-rho}
\E[\CR(\rho,0)^\lambda]=\frac{\sinh(\frac{\pi}{2}\sqrt{12\lambda-1})}{\sqrt{12\lambda-1}}-\frac{2\sqrt{3}\sinh(\frac{\pi}{3}\sqrt{12\lambda-1})}{\sqrt{12\lambda-1}\log\left(\frac{(2+\sqrt{3})^{2}+\tanh^{2}\left(\frac{\pi}{12}\sqrt{12\lambda-1}\right)}{1+(2+\sqrt{3})^{2}\tanh^{2}\left(\frac{\pi}{12}\sqrt{12\lambda-1}\right)}\right)}.
\end{equation}
When $\lambda\in[0,\frac{1}{12})$, the right side of~\eqref{eq:cr-rho} is defined by analytic continuation; see the end of Section~\ref{section-intro}.
\end{proposition}

Let $\nu_\D$ be the law of the loop chosen from the counting measure over $\{\ell_i\}_{i\ge1}$; namely, $\nu_\D$ is such that $\int F(\eta)\nu_\D(d\eta)=\P\left[\sum_{i\ge1}F(\ell_i)\right]$ for any bounded measurable function $F$. The following result, based on~\cite{cfsx} and Theorem~\ref{thm-cr-mod-relation}, gives the explicit law of the conformal radius under $\nu_\D$.
\begin{lemma}\label{lem-CR-BM-counting-ell}
There is a constant $C>0$ such that for $\lambda\ge0$, we have
\begin{equation}
 \label{eq-CR-BM-counting-ell}
 \int\CR(\eta,0)^\lambda\nu_{\D}(d\eta)=C\frac{\sqrt{12\lambda-1}}{\sinh(\frac{\pi}{3}\pi\sqrt{12\lambda-1})}\log\left(\frac{(2+\sqrt{3})^{2}+\tanh^{2}\left(\frac{\pi}{12}\sqrt{12\lambda-1}\right)}{1+(2+\sqrt{3})^{2}\tanh^{2}\left(\frac{\pi}{12}\sqrt{12\lambda-1}\right)}\right).
 \end{equation}
When $\lambda\in(0,\frac{1}{12})$, the right side of~\eqref{eq-CR-BM-counting-ell} is defined via analytic continuation as before.
\end{lemma}
\begin{proof}
By combining~\cite[Lemma 5.3]{cfsx} with~\cite[Theorem 1.3]{cfsx}, we have $\frac{d\nu_{\D}}{d\SLE^{\lp}_{8/3,\D}}(\eta)=\frac{C_1}{\Mod(\eta,\S^1)}$ for some constant $C_1>0$.
Then by Theorem~\ref{thm-cr-mod-relation}, we find
\begin{equation}\label{eq:cr-integral}
\int\CR(\eta,0)^\lambda\nu_{\D}(d\eta)=C
 \frac{\sqrt{12\lambda-1}}{\sinh(\frac{\pi}{3}\sqrt{12\lambda-1})}\int_0^\infty e^{-(2\lambda-\frac{1}{6})\pi\tau}\frac{\eta(2i\tau)}{\tau}d\tau.
\end{equation}
for some constant $C>0$. 
Note that for $a>-\frac{\pi}{6}$, we have $\int_0^\infty e^{-a\tau}\eta(2i\tau)d\tau=\sqrt{\frac{\pi}{2a}}\frac{\sinh\left(\sqrt{\frac{2}{3}\pi a}\right)}{\cosh\left(\sqrt{\frac{3}{2}\pi a}\right)}$ (see e.g.~\cite[Equation (A.4)]{ARS-Annulus}) and
 $$
 \frac{d}{da}\left[-\log\left(\frac{(2+\sqrt{3})^{2}+\tanh^{2}\left(\frac{1}{2}\sqrt{\frac{\pi}{6}a}\right)}{(2-\sqrt{3})^2+\tanh^{2}\left(\frac{1}{2}\sqrt{\frac{\pi}{6}a}\right)}\right)\right]=\sqrt{\frac{\pi}{2a}}\frac{\sinh\left(\sqrt{\frac{2}{3}\pi a}\right)}{\cosh\left(\sqrt{\frac{3}{2}\pi a}\right)}.
 $$
Therefore, we obtain
 $$
 \int_0^\infty e^{-a\tau}\frac{\eta(2i\tau)}{\tau}d\tau=\log\left(\frac{(2+\sqrt{3})^{2}+\tanh^{2}\left(\frac{1}{2}\sqrt{\frac{\pi}{6}a}\right)}{1+(2+\sqrt{3})^{2}\tanh^{2}\left(\frac{1}{2}\sqrt{\frac{\pi}{6}a}\right)}\right).
 $$
for $a>-\frac{\pi}{6}$. Combined with the right side of~\eqref{eq:cr-integral}, we conclude.
\end{proof}

The upper bound of $\P[\mathsf{Bac}_\varepsilon]$ then relies on the following iterative inequality.
\begin{proposition}
 \label{prop-upper-bound-backbone}
 Let $q_0=\P[\wt\ell_1\cap\A_{1/2}\neq\emptyset]\in(0,1)$. Then
 there is a constant $C_0>0$ such that for any $\varepsilon\in(0,10^{-4})$,
 $$
 \P[\Bac_\varepsilon]\le \frac{C_0}{\log|\log\varepsilon|}+q_0\P[\Bac_{5\sqrt{\varepsilon}}].
 $$
\end{proposition}
\begin{proof}
Note that
 \begin{align}
 \P[\Bac_\varepsilon]&\le\P[\ell_1\cap5\sqrt{\varepsilon}\D\neq\emptyset]+\P[\ell_1\cap5\sqrt{\varepsilon}\D=\emptyset,\Bac_\varepsilon]\nonumber\\
 &\le \P[\ell_1\cap5\sqrt{\varepsilon}\D\neq\emptyset]+\P[\wt\ell_1\cap5\sqrt{\varepsilon}\D\neq\emptyset]+\P[\wt\ell_1\cap5\sqrt{\varepsilon}\D=\emptyset,\Bac_\varepsilon]\nonumber\\
 &= \P[\ell_1\cap5\sqrt{\varepsilon}\D\neq\emptyset]+\P[\wt\ell_1\cap5\sqrt{\varepsilon}\D\neq\emptyset]+\P[\wt\ell_1\cap5\sqrt{\varepsilon}\D=\emptyset,\wt\ell_1\cap\A_{1/2}\neq\emptyset, \Bac_\varepsilon]\label{eq:upper-1}
 \end{align}
Here the last line follows from that $(\wt\ell_1\cap(5\sqrt{\varepsilon}\D\cup\A_{1/2})=\emptyset)\cap\Bac_\varepsilon=\emptyset$.
By Lemma~\ref{lem-CR-BM-ell1}, Corollary~\ref{cor-estimate-cr-rho} and using Koebe's 1/4 theorem, there exist some positive constants $C,C'$ and $C_0$ such that
\begin{align}
\P[\ell_1\cap5\sqrt{\varepsilon}\D\neq\emptyset]+\P[\wt\ell_1\cap5\sqrt{\varepsilon}\D\neq\emptyset]&\le\P[\CR(\ell_1,0)<20\sqrt{\varepsilon}]+\P[\CR(\wt\ell_1,0)<20\sqrt{\varepsilon}]\nonumber\\
 & \le C\varepsilon^{\frac{1}{8}}+C'\frac{1}{\log|\log\varepsilon|}\le \frac{C_0}{\log|\log\varepsilon|}.\label{eq:upper-2}
\end{align}

Let $q_0:=\P[\wt\ell_1\cap\A_{1/2}\neq\emptyset]\in(0,1)$. Then
\begin{equation}\label{eq:upper-3}
\P[\wt\ell_1\cap5\sqrt{\varepsilon}\D=\emptyset,\wt\ell_1\cap\A_{1/2}\neq\emptyset,\Bac_\varepsilon]\le q_0\P[\Bac_\varepsilon|\wt\ell_1\cap5\sqrt{\varepsilon}\D=\emptyset,\wt\ell_1\cap\A_{1/2}\neq\emptyset].
\end{equation}
Let $g:D(\wt\ell_1)\to\D$ be the conformal map such that $g(0)=0,g(B_{s_1})=1$.
By Lemma~\ref{lem-independent-decomposition-BM}, we see that $(g(B_t))_{t\in[0,s_1]}$ is independent of $B[s_1,\tau_\D]$, and has the same law (up to a time change) as $B[0,\tau_{\D}]$ conditioned on $B_{\tau_\D}=1$. Hence, if we denote $\wt\P$ to be the law of $(g(B_t))_{t\in[0,s_1]}$ conditioned on the event $\{\wt\ell_1\cap5\sqrt{\varepsilon}\D=\emptyset\}\cap\{\wt\ell_1\cap\A_{1/2}\neq\emptyset\}$, then $\wt\P$ is still the same as (up to a time change) the law of $B[0,\tau_{\D}]$ conditioned on $B_{\tau_\D}=1$.
By Lemma~\ref{lem-variant-Koebe-1/4}, 
on the event $\{\wt\ell_1\cap5\sqrt{\varepsilon}\D=\emptyset\}\cap\{\wt\ell_1\cap\A_{1/2}\neq\emptyset\}$,
we have $\overline{g(\varepsilon\D)}\subset5\sqrt{\varepsilon}\D$ and 
$g(\frac{1}{2}\D\cap D(\wt\ell_1))\supset \frac{1}{2}\D$. Then we find
\begin{equation}\label{eq:upper-4}
\P[\Bac_\varepsilon|\wt\ell_1\cap5\sqrt{\varepsilon}\D=\emptyset,\wt\ell_1\cap\A_{1/2}\neq\emptyset]\le \wt\P[\Bac_{5\sqrt{\varepsilon}}]=\P[\Bac_{5\sqrt{\varepsilon}}],
\end{equation}
where the last equality follows from the rotational invariance of $B[0,\tau_\D]$. The result then follows from combining~\eqref{eq:upper-1},~\eqref{eq:upper-2},~\eqref{eq:upper-3} and~\eqref{eq:upper-4}.
\end{proof}

Now we prove the upper bound for $\P[\Bac_\varepsilon]$, finishing the proof of Theorem~\ref{thm:backbone}.
\begin{proof}[Proof of Theorem~\ref{thm:backbone}, the upper bound]
Let $\varepsilon\in(0,10^{-4})$ and $F(\varepsilon):=\P[\Bac_\varepsilon]$. Note that the function $x\mapsto\frac{1}{\log|\log x|}$ is increasing on $(0,10^{-4})$ and there is a constant $C>0$ such that $\frac{1}{\log|\log(25x)|}\le\frac{C}{\log|\log x|}$ for any $x\in(0,10^{-4})$. Then for each $n\in\mathbbm{Z}_+$ with $25\varepsilon^{\frac{1}{2^n}}<10^{-4}$, by applying Proposition~\ref{prop-upper-bound-backbone} for $n$ times, we find
\begin{align}
 F(\varepsilon)
 &\le C_0\sum\limits_{k=0}^{n-1}\frac{q_0^k}{\log|\log(5^{2-\frac{1}{2^{k-1}}}\varepsilon^{\frac{1}{2^k}})|}+q_0^nF(5^{2-\frac{1}{2^{n-1}}}\varepsilon^{\frac{1}{2^n}})\nonumber\\
 &\le \frac{C_0}{1-q_0}\frac{1}{\log|\log(25\varepsilon^{\frac{1}{2^n}})|}+q_0^n\le\frac{C_0C}{1-q_0}\frac{1}{\log|\log(\varepsilon^{\frac{1}{2^n}})|}+q_0^n\nonumber\\
 &=\frac{C_0C}{1-q_0}\frac{1}{\log|\log(\varepsilon)|-n\log2}+q_0^n.\label{eq-proof-upper-bound-backbone}
\end{align}

selected.post_theorem_intro_text:
\begin{remark}
The same result also holds when $\frac{1}{2}\mathbbm{S}^1$ in~\eqref{eq:def-backbone} is changed to any fixed $r\mathbbm{S}^1$ with $r\in(0,1)$ (and for sufficiently small $\varepsilon$), except that the corresponding constants in~\eqref{eq:bb-proba} will depend on $r$.
\end{remark}

Note that the backbone event $\Bac_\varepsilon$ is closely related to the spatial distribution of the \emph{cut points} of $B[0,\tau_\mathbbm{D}]$. Indeed, our proof of Theorem~\ref{thm:backbone} is based on our recent paper with Fu and Sun~\cite{cfsx}, from which we can define a layer structure for the cut points of $B[0,\tau_\mathbbm{D}]$ and then solve it explicitly; see Section~\ref{section-backbone-1}. We mention that~\cite{cfsx} heavily relies on the connection between planar Brownian motion and $\SLE_{8/3}$, and especially their coupling with Liouville quantum gravity (LQG). It would be quite interesting to see if there is a derivation of Theorem~\ref{thm:backbone} without relying on LQG.

Theorem~\ref{thm:backbone} is related to a certain kind of special points of Brownian motion. Namely, let
\[
\mathcal{B}:=\{B_s:s\in[0,\tau_\mathbbm{D}) \text{ and there exists } \varepsilon>0 \text{ such that } (B_{s+u})_{0\le u\le\varepsilon} \text{ does not have a cut point}\}.
\]
Then Theorem~\ref{thm:backbone} indicates that $\mathcal{B}$ is non-empty and has Hausdorff dimension 2. Furthermore, it also suggests that the Hausdorff measure of $\mathcal{B}$ with the gauge $r\mapsto r^2\log\frac{1}{r}\log\log\frac{1}{r}\log\log\log\frac{1}{r}$~would exist and be non-trivial (since the Hausdorff gauge of $B[0,\tau_\mathbbm{D}]$ itself is $r\mapsto r^2\log\frac{1}{r}\log\log\log\frac{1}{r}$, see e.g.~\cite{LG85}). In particular, due to that planar Brownian motion a.s.~has no double cut points~\cite{BL}, we know that $\mathcal{B}$ contains the set of double points of $(B_t)_{0\le t\le\tau_\mathbbm{D}}$, which has the Hausdorff gauge $r\mapsto r^2(\log\frac{1}{r}\log\log\log\frac{1}{r})^2$~\cite{LG87}.

\subsection{Outlook and discussions}
\label{section-discussion}

Here we give several remarks and related questions before going into the proof.

\begin{itemize}
\setlength{\itemsep}{0pt}
\setlength{\parskip}{0pt}
\setlength{\parsep}{0pt}

\item One can similarly consider the probability that there exist $2n$ disjoint subpaths on $B[0,\tau_\mathbbm{D}]$ joining $\varepsilon\mathbbm{S}^1$ and $\frac{1}{2}\mathbbm{S}^1$ with $n\ge2$. Note that for $n\ge2$, such $2n$-arm probability is not straightforwardly related to the cut points of $B[0,\tau_\mathbbm{D}]$. Instead, one need to consider the $(2n-1)$-tuples of the local cut points such that removing these $(2n-1)$ cut points from the trajectory $B[0,\tau_\mathbbm{D}]$, $0$ and $B_{\tau_\mathbbm{D}}$ are not in the same connected component of the remaining set. However, analyzing such tuples of local cut points (e.g.~the counterpart of the layer structure in Section~\ref{section-backbone-1}) becomes much more complicated, and it seems difficult to solve them explicitly. We mention that similar difficulty also appears in deriving the monochromatic $k$-arm exponents of critical planar percolation for $k\ge3$, see~\cite[Remark 2.3]{nolin2024backboneexponenttwodimensionalpercolation}.

\item 
There is also a natural half-plane variant of our setup. Namely, let $(e_t)_{t\ge0}$ be the Brownian excursion on the upper half plane $\mathbbm{H}$ from $0$ to $\infty$, and define $R\mathbbm{S}^+:=R\mathbbm{S}^1\cap\mathbbm{H}$ for $R>0$. Then for $n\ge1$, consider the asymptotic probability that 
there exists $(2n+1)$ disjoint subpaths on the trajectory of $(e_t)$ joining $\mathbbm{S}^+$ and $R\mathbbm{S}^+$ as $R\to\infty$.
Note that the case $n=1$ can be similarly related to the cut points of $(e_t)$, which has been proven in~\cite[Theorem 4]{brownian-beads}.

\item In our forthcoming work~\cite{cx}, we will extend the result of this paper to the Brownian loop soup cases. Let $(B_t)_{0\le t\le\tau_\mathbbm{D}}$ be as before, and let $\mathcal{L}$ be an independent Brownian loop soup on $\mathbbm{D}$ with intensity $\frac{c}{2}$ for $c\in(0,1]$. 
For a subset $A\subset\ol\mathbbm{D}$, denote $\mathcal{C}(A)$ to be the union of $A$ and all loop-soup clusters in $\mathcal{L}$ intersecting with $A$, 
and let $H:=\mathcal{C}(B[0,\tau_\mathbbm{D}])$. 
However, unlike the Brownian motion case, 
there is a positive probability that $0$ itself can have two disjoint subpaths (except on $0$) on $H$
connected to $\frac{1}{2}\mathbbm{S}^1$. Moreover, in~\cite{cx} we will show the following
\begin{theorem}
We say $t\in(0,\tau_\mathbbm{D}]$ is a cut time of $H$ if $\mathcal{C}(B[0,t])\cap \mathcal{C}(B[t,\tau_\mathbbm{D}])=B_t$. Let $t_1$ be the largest cut time of $H$ such that the boundary of $\mathcal{C}(B[0,t_1])$ is a simple loop, and denote $E$ to be the event that $t_1$ is the smallest cut time of $H$. 
Then for $c\in(0,1)$,
\begin{equation}\label{eq:p_e}
