We are now ready to state our first main result, which shows that the condition $\cH^{n+\alpha}_{(\alpha)}(E) = 0$ is sufficient for the removability of the set $E$ in the class of $\alpha$-Hölder continuous solutions. More precisely, we prove the following result.

\begin{equation}\tag{S1}\label{as:growth}
        \cA(x,t,\xi) \cdot \xi \geq \nu |\xi|^p
        \quad \text{and} \quad
        |\cA(x,t,\xi)| \leq L |\xi|^{p-1}
\end{equation}

\begin{equation}\tag{S2a}\label{as:monotonicity-weaker}
            \left(\cA(x,t,\xi)-\cA(x,t,\eta) \right) \cdot \left( \xi - \eta \right) > 0 \text{ for all $\xi$, $\eta \in \R^n$ with } \xi \neq \eta\,,\end{equation}

\begin{equation}
    \label{eq: def Hausdorff measure}
    \cH^{\sigma}_{(\alpha)}(E)
= \lim_{\delta\downarrow 0}\ \inf\left\{\sum_{i=1}^\infty r_i^{\sigma}:\ 
E\subset \bigcup_{i=1}^\infty Q_{r_i,r_i^\alpha}(z_i),\ 0<r_i<\delta\right\},    
\end{equation}

\begin{equation}\label{eq_main}
    \partial_t u-\div \cA(x,t,\nabla u)=0\,,
\end{equation}

The converse result to Theorem~\ref{thm:main} is also true under slightly stronger assumptions. First of all, we require strict monotonicity of the operator $\cA$ in Theorem~\ref{thm: necessity of Hausdorff zero}. Nonetheless, a broad class of operators is considered, including the $p$-Laplacian. The upper threshold $\kappa$ appearing in~\Cref{thm: necessity of Hausdorff zero} is related to the optimal local H\"older continuity of solutions to~\eqref{eq_main}. For smooth operators $\cA$, one can always take $\kappa = 1$, see \cite{KuusiMingione2013}.
To the best of our knowledge, Theorem~\ref{thm: necessity of Hausdorff zero} is new even in the case $p=2$.
\begin{theorem}
\label{thm: necessity of Hausdorff zero}
Let $\cA$ satisfy \eqref{as:growth} and \eqref{as:monotonicity-stronger}, let $\kappa \in (0, 1]$ be such that~\eqref{eq: kappa hölder cont of sols} holds, and let $0<\alpha<\kappa$. Let $E\subset\Omega_T$ be a closed set with $\mathcal{H}^{n+\alpha}_{(\alpha)}(E)>0$. Then, there exists a function $u$ which is locally $\alpha$-Hölder continuous in $\Omega_T$ with respect to $d_\alpha$, such that $u$ is a solution of \eqref{eq_main} in $\Omega_T\backslash E$, but not in $\Omega_T$. 
\end{theorem}

\section{Proof of Theorem \ref{thm:main}}\label{sec:sufficiency}
The proof of Theorem~\ref{thm:main} is composed of several ingredients, presented mainly in Lemmas~\ref{lemma: general estimate for measure of supersol}-\ref{lemma: decay of measure}. A crucial step in the proof is to establish a decay estimate for the Riesz measure associated to the solution of the obstacle problem with H\"older continuous obstacle, see Lemma~\ref{lemma: decay of measure}. To this end, we provide estimates concerning supersolutions to~\eqref{eq_main}, expressed in Lemmas~\ref{lemma: general estimate for measure of supersol} and~\ref{lem:meas-inq}. We begin with the following estimate.
{
\begin{lemma}
\label{lemma: general estimate for measure of supersol}
 Let $\Omega \subset \mathbb{R}^n$ be open. Let $u$ be a non-negative and locally bounded supersolution of \eqref{eq_main} in $\Omega_T$ and let 
 \begin{equation}\label{eq:measure_prob}
 \mu = \partial_t u - \div \cA (x,t,\nabla u) ,
 \end{equation}
 be the associated Riesz measure.
 Let $z_0 \in \Omega_T$ and $r > 0$ be such that $Q \coloneqq Q_{2r, (2r)^{\alpha}}(z_0) \Subset \Omega_T$.
 Then, there exists a positive constant $C = C(n, p, \nu, L)$ such that
 \begin{equation*}
 \mu \left(Q_{r, r^{\alpha}}(z_0) \right) \leq Cr^n \left(r^{(2-p)\alpha}\sup_Q u^{p-1} + r^{\frac{(2-p)\alpha}{p}}\sup_Q u^{\frac{2(p-1)}{p}} + \sup_Q u\right)\,.
 \end{equation*}
\end{lemma}
\begin{proof}
Let $\eta$ be a standard cut-off function such that $0 \leq \eta \leq 1$, $\eta \equiv 1$ on $Q_{r, r^{\alpha}}(z_0)$, $\supp \eta \subseteq Q$, and $|\nabla \eta| \leq \frac{c}{r}$, $|\partial_t \eta| \leq \frac{c}{r^{p + (2-p)\alpha}}$ for a constant $c = c(n)$. Then, by the definition of $u$ and Assumption \eqref{as:growth} on $\cA$, we have
 \begin{equation}\label{eq:sep25-1}
 \begin{split}
 \mu \left(Q_{r, r^{\alpha}}(z_0) \right) \leq \int_{Q} \eta^p d\mu &= \int_{Q} p\eta^{p-1} \cA(x, t, \nabla u) \cdot \nabla \eta \dx \dt - \int_{Q} pu\eta^{p-1} \partial_t \eta \dx \dt\\
 &\leq C\int_Q \eta^{p-1}|\nabla u|^{p-1}|\nabla \eta| + u|\partial_t \eta| \dx \dt\,,
 \end{split}
 \end{equation}
 where the first inequality holds since $u$ is a weak solution of \eqref{eq:measure_prob} in the sense of Definition \ref{def:solution-measure-data}. Furthermore, by the bound on $\partial_t\eta$, we have
 \begin{equation}\label{eq:sep25-2}
 \int_{Q} u|\partial_t \eta|\dx\dt \leq Cr^n \sup_Q u\,.
 \end{equation}
 On the other hand, H\"older's inequality together with Lemma~\ref{lem:Cacciopoli} gives
 \begin{align*}
 \int_Q \eta^{p-1}|\nabla u|^{p-1}|\nabla \eta|\dx\dt &\leq
 \left( \int_Q \eta^p |\nabla u|^p \dx \dt \right)^{\frac{p-1}{p}}\left( \int_Q |\nabla \eta|^p \dx \dt \right)^{\frac{1}{p}}\\
 &\leq Cr^{\frac{n + (2-p)\alpha}{p}} \left(\sup_Q u^{p} \int_{Q} |\nabla \eta|^p\dx \dt + \sup_Q u^{2}\int_Q |\partial_t \eta^p| \dx \dt\right)^{\frac{p-1}{p}}\\
 &\leq Cr^{n+ (2-p)\alpha}\sup_Q u^{p-1} + Cr^{n + \frac{(2-p)\alpha}{p}}\sup_Q u^{\frac{2(p-1)}{p}}\,.
 \end{align*}
 Combining the last estimate with~\eqref{eq:sep25-1} and~\eqref{eq:sep25-2} yields the desired conclusion.
\end{proof}
}
Truncations of supersolutions to~\eqref{eq_main} are themselves supersolutions, see \cite[Lemma 3.2]{kortekuusiparviainen2010-superparabolic} for the proof in our setting.
Tracing the two Riesz measures in this proof produces the estimate in the following lemma. For the convenience of the reader, we give the full proof.
\begin{lemma}\label{lem:meas-inq}
Let $\Omega \subset \mathbb{R}^n$ be open. Let $u$ be a continuous supersolution to \eqref{eq_main} in $\Omega_T$ and let 
\begin{equation*}
 \mu = \partial_t u - \div \cA (x,t,\nabla u)
\end{equation*}
be the associated Riesz measure. Let $k\in\mathbb R$. Then, $u_k=\min(u,k)$ is a supersolution to \eqref{eq_main}. Additionally, let
\begin{equation}\label{eq:nov10-1}
 \mu_k=\partial_t u_k -\div \mathcal A(x,t,\nabla u_k)
\end{equation}
be the Riesz measure of $u_k$. Then, for any $\varphi\in \Cz^\infty_0(\Omega_T)$, it holds
\begin{equation}
 \label{eq: ineq for measure of cutoff supersol}
 \int_{\Omega_T} \chi_{\{u<k\}}\varphi\dmu \leq \int_{\Omega_T} \varphi \d\mu_k\,.
\end{equation}

The proof of \Cref{thm: necessity of Hausdorff zero} follows in a straightforward way from the previous results.
\begin{proof}[Proof of \Cref{thm: necessity of Hausdorff zero}]
Let $\mu$ be a measure as in \Cref{cor:parabolic-frostman}, with $\sigma=n+\alpha$. By Lemma \ref{lemma:exis_measure}, there exists an $\mathcal A$-superparabolic function $u$ in $\Omega_T$ satisfying~\eqref{eq: measure RHS}, which is a weak solution in $\Omega_T\backslash E$, since $\supp \mu\subset E$. By \Cref{thm: measure condition implies hölder cont}, $u$ is locally $\alpha$-Hölder continuous with respect to $d_\alpha$. To see this, let $z_0\in \Omega_T$ be a Lebesgue point of $u^{p-1}$ and let $C$ be as in \eqref{eq: intrinsic parameter in osc of sol meas data}. Let $0<R_0<1$ be such that $Q_{R_0,C R_0^\alpha}(z_0)\Subset\Omega_T$. Let $0<R<R_0$. We have $C\max(1,R^-\alpha)=CR^{-\alpha}$. Moreover, choosing $R$ small enough, since $z_0$ is a Lebesgue point, we have
\begin{equation*}
 \left(\dashint_{Q_{R, C R^\alpha}(z_0)} \lvert u-u_{Q_{R,C R^\alpha}(z_0)}\rvert^{p-1}\dx\dt\right)^\frac{1}{p-1} < 1,
\end{equation*}
and hence \eqref{eq: Hölder cont of meas data sol} together with a simple covering argument implies the local Hölder continuity. Finally, $u$ does not solve \eqref{eq_main} in $\Omega_T$, since $\mu\not \equiv 0$.
\end{proof}

